/**
 * LOGO OFICIAL — Todo para el Asador MDQ
 * Imagen real provista por el cliente (PNG original, exportada a WebP
 * y embebida en base64 para que quede dentro del bundle single-file).
 * Uso: <LogoMark className="w-14 h-14" />
 */

type Props = {
  className?: string;
  uid?: string;
  title?: string;
};

const LOGO_DATA_URL =
  "data:image/webp;base64,";

export default function LogoMark({
  className = "w-14 h-14",
  title = "Todo para el Asador MDQ",
}: Props) {
  return (
    <img
      src={LOGO_DATA_URL}
      alt={title}
      className={`${className} object-contain`}
      draggable={false}
    />
  );
}
